#!/usr/bin/env node
// Turns the generated Wrangler config into one that can actually be deployed,
// and refuses to produce one that cannot.
//
// The build writes dist/server/wrangler.json by merging wrangler.jsonc with
// what the Cloudflare plugin contributes. Two things are true of that file and
// both of them have cost a deploy:
//
//   1. It carries REPLACE_ME_D1_DATABASE_ID, because a database id identifies
//      one specific database and does not belong in this repository. The real
//      value arrives here as an environment variable at deploy time.
//
//   2. It is regenerated by every build, so editing it by hand fixes nothing.
//      This script runs after the build and before the deploy, every time.
//
// The checks are the point as much as the substitution. A deploy that uploads
// the wrong bindings does not look like a failure, it looks like an app that
// quietly saves nothing, and that is much more expensive than a build that
// stops here with a readable message.

import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const PLACEHOLDER_DATABASE_ID = "REPLACE_ME_D1_DATABASE_ID";
/** Set in the deploy environment. Not a secret, and still not ours to commit. */
const ID_VARIABLES = ["D1_DATABASE_ID", "CLOUDFLARE_D1_DATABASE_ID"];

/** A UUID, which is the only shape a D1 database id comes in. */
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/**
 * Everything that must be true of a config before it is worth uploading.
 *
 * Exported so tests can run it against deliberately broken configs rather than
 * only against whatever this build happened to produce.
 */
export function checkDeployConfig(config) {
  const problems = [];

  const bindings = [
    ...(config.d1_databases ?? []),
    ...(config.r2_buckets ?? []),
    ...(config.kv_namespaces ?? []),
    ...(config.durable_objects?.bindings ?? []),
  ].map((entry) => entry.binding);

  const seen = new Set();
  const duplicated = [...new Set(bindings.filter((name) => (seen.has(name) ? true : (seen.add(name), false))))];
  if (duplicated.length) {
    // wrangler refuses this itself, but it refuses after a person has waited
    // for a build, and its message does not say where the second one came from.
    problems.push(`These binding names are declared more than once: ${duplicated.join(", ")}. The usual cause is .openai/hosting.json's d1 and r2 keys being synthesised alongside wrangler.jsonc's real ones. See the hasWranglerConfig guard in vite.config.ts.`);
  }

  const flags = config.compatibility_flags ?? [];
  const nodeCompat = flags.filter((flag) => flag === "nodejs_compat").length;
  if (nodeCompat !== 1) {
    problems.push(`nodejs_compat must be supplied exactly once, not ${nodeCompat} times. Got ${JSON.stringify(flags)}. It comes from localBindingConfig in vite.config.ts; wrangler.jsonc keeps compatibility_flags empty on purpose.`);
  }

  const blob = JSON.stringify({ d1: config.d1_databases, r2: config.r2_buckets });
  if (/site-creator-/.test(blob)) {
    problems.push("A site-creator placeholder binding reached the build. That is the other platform's manifest leaking into this one.");
  }
  if (/00000000-0000-4000-8000-000000000000/.test(blob)) {
    problems.push("The all-zeros placeholder database id reached the build. Deploying this would write every session to a database that is not anybody's.");
  }

  // The four the worker actually reads, each enumerated in wrangler.jsonc
  // against the line that reads it.
  if (config.assets?.binding !== "ASSETS") problems.push("The ASSETS binding is missing. Without it the app serves no static files at all.");
  if (config.images?.binding !== "IMAGES") problems.push("The IMAGES binding is missing. /_vinext/image is handled in worker/index.ts and needs it.");
  const d1Bindings = (config.d1_databases ?? []).map((entry) => entry.binding);
  if (d1Bindings.join() !== "DB") problems.push(`Expected exactly one D1 binding named DB, got ${JSON.stringify(d1Bindings)}. Every route reads it through getProductRuntime.`);

  for (const entry of config.d1_databases ?? []) {
    if (entry.database_id === PLACEHOLDER_DATABASE_ID) {
      problems.push(`The D1 database id is still ${PLACEHOLDER_DATABASE_ID}. Set ${ID_VARIABLES[0]} in the deploy environment to the id shown in the Cloudflare dashboard under Storage and Databases, D1.`);
    } else if (!UUID.test(String(entry.database_id ?? ""))) {
      problems.push(`The D1 database id is not a UUID: ${JSON.stringify(entry.database_id)}. Check the value of ${ID_VARIABLES[0]}.`);
    }
  }

  return problems;
}

/** The id from the deploy environment, or "" when nothing is set. */
function databaseIdFromEnvironment(env = process.env) {
  for (const name of ID_VARIABLES) {
    const value = (env[name] ?? "").trim();
    if (value) return value;
  }
  return "";
}

/** Substitution only. Validation is separate so it can run on the result. */
export function applyDatabaseId(config, databaseId) {
  if (!databaseId) return config;
  return {
    ...config,
    d1_databases: (config.d1_databases ?? []).map((entry) =>
      entry.database_id === PLACEHOLDER_DATABASE_ID ? { ...entry, database_id: databaseId } : entry,
    ),
  };
}

function main() {
  const path = fileURLToPath(new URL("../dist/server/wrangler.json", import.meta.url));

  let config;
  try {
    config = JSON.parse(readFileSync(path, "utf8"));
  } catch {
    console.error(`Could not read ${path}. Run the build first: npm run build`);
    process.exit(1);
  }

  const prepared = applyDatabaseId(config, databaseIdFromEnvironment());
  const problems = checkDeployConfig(prepared);

  if (problems.length) {
    console.error("This build cannot be deployed as it stands:\n");
    for (const problem of problems) console.error(`  - ${problem}\n`);
    process.exit(1);
  }

  writeFileSync(path, JSON.stringify(prepared, null, 2));
  const database = prepared.d1_databases[0];
  // The id is not printed. It is not a secret, and a build log is still not
  // the place to start putting identifiers that name one account's database.
  console.log(`Deploy config ready: worker "${prepared.name}", D1 "${database.database_name}", bindings ASSETS, IMAGES, DB${(prepared.r2_buckets ?? []).length ? ", UPLOADS" : " (no R2)"}.`);
}

// Importable by tests without running.
if (process.argv[1] && fileURLToPath(new URL(import.meta.url)) === process.argv[1]) main();
